 const entries=[['/browse','gamepad',t('Bozor','Маркет','Marketplace'),!filters.category&&!filters.game&&filters.sort!=='price_asc'],['/top-up','wallet','Top Up',false],['/browse?category=accounts','user',t('Akkauntlar','Аккаунты','Accounts'),filters.category==='accounts'],['/browse?category=currency','layers',t('O‘yin valyutasi','Игровая валюта','Game Currency'),filters.category==='currency'],['/browse?category=services','settings',t('O‘yin xizmatlari','Игровые услуги','Game Services'),filters.category==='services'],['/browse?sort=price_asc','ticket',t('Eng arzon','Самые дешёвые','Lowest prices'),filters.sort==='price_asc'&&!filters.category&&!filters.game]];
